        over_ride_adm = over_ride_adm.replace("\\\\", "\\")
        over_ride_ext = over_ride_adm + '|||seatbid.0.bid.0.ext.skadn.ext@{"skpv":{"video":{"onclose":true,"ondelayms":2000},"ec":{"onclose":true,"ondelayms":3000}}}'

        req = request_payload.jaeger_v5_ios(pub_app_id, placement, ifa=gen_device_id())
        r = post(ads_v5_endpoint_qa, json=req,
                 headers=platform_headers(src_ip=au_ip, rtb_selector=rtb_ids,
                                          sdk_version=sdk_v, debug='jaeger', override_bid_response_any=over_ride_ext))

        assert_response_status_code(r.status_code, HTTPStatus.OK)
        assert_valid_schema(r.json(), response_schema.ads_v5)
        response_payload = r.json()
        ad_markup = response_payload['ads'][0]['ad_markup']
        normal_replacements = ad_markup['templateSettings']['normal_replacements']
        assert_keys_exist(normal_replacements, "APP_STORE_ON_VIDEO_CLOSE")
        assert_keys_exist(normal_replacements, "APP_STORE_ON_ENDCARD_CLOSE")
        assert_that(normal_replacements["APP_STORE_ON_VIDEO_CLOSE"], equal_to("true"))
        assert_that(normal_replacements["APP_STORE_ON_ENDCARD_CLOSE"], equal_to("true"))



